// Exact peer metadata-only Auth/cascade/partition lock audit, frozen for local tests.
export const AUTH_DELETE_LOCKS_SQL="with recursive edges(parent,child) as (\n select confrelid,conrelid from pg_catalog.pg_constraint where contype='f' and confdeltype in ('c','n','d')\n union select inhparent,inhrelid from pg_catalog.pg_inherits\n), protected(relation) as (\n select c.oid from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace where n.nspname='auth'\n union select e.child from edges e join protected p on p.relation=e.parent\n)\nselect not exists(select 1 from pg_catalog.pg_locks l join protected p on p.relation=l.relation\n where l.pid=pg_backend_pid() and l.granted and l.mode<>'AccessShareLock') as clear";
